window.search = Object.assign(window.search, JSON.parse('{"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":true,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}},"doc_urls":["前言.html#前言","近古/RAN-Min.html#冉閔","近古/RAN-Min.html#人物形象","近古/RAN-Min.html#本傳","近古/RAN-Min.html#晉書卷一百七-載記第七","近古/RAN-Min.html#史評","近古/RAN-Min.html#知乎文章冉吹看了沉默冉黑看了流泪对冉闵的正本清源","近古/RAN-Min.html#一所谓三姓家奴问题","近古/RAN-Min.html#二汉奸问题与冉闵反胡动机","近古/RAN-Min.html#三冉闵反胡斗争是否坚定","近古/RAN-Min.html#四当时的时代背景与冉闵反胡之正义性"],"index":{"fields":["title","body","breadcrumbs"],"pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5","index":{"body":{"root":{"docs":{},"df":0,"5":{"docs":{"10":{"tf":1.0}},"df":1}}},"breadcrumbs":{"root":{"docs":{},"df":0,"5":{"docs":{"10":{"tf":1.0}},"df":1}}},"title":{"root":{"docs":{},"df":0}}},"documentStore":{"save":true,"docs":{"0":{"body":"本倉庫記錄中華歷史上的英雄人物。","breadcrumbs":"前言 » 前言","id":"0","title":"前言"},"1":{"body":"人物形象 本傳 晉書卷一百七 載記第七 史評 [知乎文章—— 冉吹看了沉默，冉黑看了流泪——对冉闵的正本清源 一、所谓“三姓家奴”问题 二、“汉奸”问题与冉闵反胡动机 三、冉闵反胡斗争是否坚定 四、当时的时代背景与冉闵反胡之正义性","breadcrumbs":"冉閔 » 冉閔","id":"1","title":"冉閔"},"10":{"body":"冉闵反胡，自邺城杀胡始，民族仇杀无疑是一种极端的行为，我们当然不能提倡，而且要反对，很多人因此非议冉闵。但是，你们有没有考虑当时的时代背景？为什么会出现这么激烈的民族仇杀？这责任在于冉闵吗？ （5）为“冉闵特殊的生活背景”，前文已述 由此可以看出，冉闵反胡不仅是出于他自己的意志，也代表了中原汉族人民的心声，因此他才会广受汉族支持。 闵知胡之不为己用，班令内外：「赵人斩一胡首送凤阳门者，文官进位三等，武官乘拜牙门。」一日之中，斩首数万。 闵亲帅赵人以诛胡、羯，无贵贱、男女、少长皆斩之，〔少，诗照翻。长，知两翻。〕死者二十余万，尸诸城外，悉为野犬豺狼所食。 其屯戍四方者，闵皆以书命赵人为将帅者诛之，或高鼻多须滥死者半。〔高鼻多须，其状似羯、胡，故亦见杀。将，即亮翻。帅，所类翻。〕 ——《资治通鉴》 有人因为冉闵诛胡误杀了很多高鼻深目的汉人而贬低他，殊不知这不是冉闵一个人杀的，是冉闵带领邺城的汉人一块杀的，而且是误杀（再说汉族人里有这种极为特殊长相的肯定是少数），他们的目的是杀胡人，结合当时时代背景，他们这样做是具有反抗异族压迫的正义性的，可以视作起义。 注:感谢评论区 @风龙云虎 的指正:误杀高鼻多须汉人的现象并未发生在邺城，从“其屯戍四方者，闵皆以书命赵人为将帅者诛之，或高鼻多须滥死者半。”这句看，应该是四方响应屠胡时失控出现了误杀。 历史上的起义，不乏有各种劣迹，这是应当批判的，但是我们也要具体问题具体分析，不能因为其中的局限性就否认整个起义的正义性和进步性。从历史唯物主义的角度出发，我们应当承认冉闵诛胡是具有正义性、进步性的，正义性体现在反抗异族压迫（不仅有民族压迫，还有阶级压迫），进步性体现在为当时其他中原异族统治者提供了教训，之后统治中原的异族统治者再怎么压迫汉人毕竟也比后赵温和得多。","breadcrumbs":"冉閔 » 四、当时的时代背景与冉闵反胡之正义性","id":"10","title":"四、当时的时代背景与冉闵反胡之正义性"},"2":{"body":"","breadcrumbs":"冉閔 » 人物形象","id":"2","title":"人物形象"},"3":{"body":"","breadcrumbs":"冉閔 » 本傳","id":"3","title":"本傳"},"4":{"body":"閔字永曾，小字棘奴，季龍之養孫也。父瞻，字弘武， 本姓冉，名良，魏郡內黃人也。其先漢黎陽騎都督，累世牙門。勒破陳午，獲瞻，時年十二，命季龍子之。驍猛多力，攻戰無前。歷位左積射將軍、西華侯。閔幼而果銳，季龍撫之如孫。及長，身長八尺，善謀策，勇力絕人。拜建節將軍，徙封修成侯，歷位北中郎將、遊擊將軍。季龍之敗于昌黎，閔軍獨全，由此功名大顯。及敗梁犢之後，威聲彌振，胡夏宿將莫不憚之。 永和六年，殺石鑒，其司徒申鐘、司空郎闓等四十八人上尊號于閔，閔固讓李農，農以死固請，於是僭即皇帝位於南郊，大赦，改元曰永興，國號大魏，復姓冉氏。追尊其祖隆元皇帝，考瞻烈祖高皇帝，尊母王氏為皇太后，立妻董氏為皇后，子智為皇太子。以李農為太宰、領太尉、錄尚書事，封齊王，農諸子皆封為縣公。封其子胤、明、裕皆為王。文武進位三等，封爵有差。遣使者持節赦諸屯結，皆不從。 石祗聞鑒死，僭稱尊號于襄國，諸六夷據州郡擁兵者皆應之。閔遣使臨江告晉曰：「胡逆亂中原，今已誅之。若能共討者，可遣軍來也。」朝廷不答。閔誅李農及其三子，並尚書令王謨、侍中王衍、中常侍嚴震、趙升等。晉盧江太守袁真攻其合肥，執南蠻校尉桑坦，遷其百姓而還。 石祗遣其相國石琨率眾十萬伐鄴，進據邯鄲。祗鎮南劉國自繁陽會琨。閔大敗琨于邯鄲，死者萬餘。劉國還屯繁陽。苻健自枋頭入關。張賀度、段勤與劉國、靳豚會於昌城，將攻鄴。閔遣尚書左僕射劉群為行臺都督，使其將王泰、崔通、周成等帥步騎十二萬次於黃城，閔躬統精卒八萬繼之，戰於蒼亭。賀度等大敗，死者二萬八千，追斬勒豚于陰安鄉，盡俘其眾，振旅而歸。戎卒三十餘萬，旌旗鐘鼓綿亙百餘里，雖石氏之盛無以過之。閔至自蒼亭，行飲至之禮，清定九流，准才授任，儒學後門多蒙顯進，于時翕然，方之為魏晉之初。 閔率步騎十萬攻石祗于襄國，署其子太原王胤為大單于、驃騎大將軍，以降胡一千配為麾下。光祿大夫韋謏啟諫甚切，閔覽之大怒，誅謏及其子孫。閔攻襄國百餘日，為土山地道，築室反耕。祗大懼，去皇帝之號，稱趙王，遣使詣慕容俊、姚弋仲以乞師。會石琨自冀州援祗，弋仲復遣其子襄率騎三萬八千至自滆頭，俊遣將軍悅綰率甲卒三萬自龍城，三方勁卒合十餘萬。閔遣車騎胡睦距襄下場長蘆，將軍孫威候琨于黃丘，皆為敵所敗，士卒略盡，睦、威單騎而還。琨等軍且至，閔將出擊之，衛將軍王泰諫曰：「窮寇固迷，希望外援。今強救雲集，欲吾出戰，腹背擊我。宜固壘勿出，觀勢而動，以挫其謀。今陛下親戎，如失萬全，大事去矣。請慎無出，臣請率諸將為陛下滅之。」閔將從之，道士法饒進曰：「太白經昴，當殺胡王，一戰百克，不可失也。」閔攘袂大言曰：「吾戰決矣，敢諫者斬！」於是盡眾出戰。姚襄、悅綰、石琨等三面攻之，祗沖其後，閔師大敗。閔潛于襄國行宮，與十餘騎奔鄴。降胡栗特康等執冉胤及左僕射劉琦等送於祗，盡殺之。司空石璞、尚書令徐機、車騎胡睦、侍中李琳、中書監盧諶、少府王郁、尚書劉欽、劉休等諸將士死者十餘萬人，於是人物殲矣。賊盜蜂起，司、冀大饑，人相食。自季龍末年而閔盡散倉庫以樹私恩。與羌胡相攻，無月不戰。青、雍、幽、荊州徙戶及諸氐、羌、胡、蠻數百餘萬，各還本土，道路交錯，互相殺掠，且饑疫死亡，其能達者十有二三。諸夏紛亂，無復農者。閔悔之，誅法饒父子，支解之，贈韋謏大司徒。 石祗使劉顯帥眾七萬攻鄴。時閔潛還，莫有知者，內外凶凶，皆謂閔已沒矣。射聲校尉張艾勸閔親郊，以安眾心，閔從之，訛言乃止。劉顯次於明光宮，去鄴二十三里，閔懼，召衛將軍王泰議之。泰恚其謀之不從，辭以瘡甚。閔親臨問之，固稱疾篤。閔怒，還宮，顧謂左右曰：「巴奴，乃公豈假汝為命邪！要將先滅群胡，卻斬王泰。」於是盡眾而戰，大敗顯軍，追奔及于陽平，斬首三萬餘級。顯懼，密使請降，求殺祗為效，閔振旅而歸。會有告王泰招集秦人，將奔關中，閔怒，誅泰，夷其三族。劉顯果殺祗及其太宰趙鹿等十餘人，傳首於鄴，送質請命。驃騎石甯奔于柏人。閔命焚祗首於通衢。 閔徐州刺史劉啟以鄄城歸順。劉顯復率眾伐鄴，閔擊敗之。還，稱號于襄國。閔徐州刺史周成、兗州刺史魏統、豫州牧冉遇、荊州刺史樂弘皆以城歸順。平南高崇、征虜呂護執洛州刺史鄭系，以三河歸順。慕容彪攻陷中山，殺閔甯北白同、幽州刺史劉准，降于慕容俊。時有雲黃赤色，起東北，長百餘丈，一白鳥從雲間西南去，占者惡之。 劉顯率眾伐常山，太守蘇亥告難於閔。閔留其大將軍蔣幹等輔其太子智守鄴，親率騎八千救之。顯所署大司馬、清河王甯以棗強降于閔，收其餘眾，擊顯，敗之，追奔及于襄國。顯大將曹伏駒開門為應，遂入襄國，誅顯及其公卿已下百餘人，焚襄國宮室，遷其百姓于鄴。顯領軍范路率眾千餘，斬關奔於枋頭。 時慕容俊已克幽、薊，略地至於冀州。閔帥騎距之，與慕容恪相遇于魏昌城。閔大將軍董閏、車騎張溫言于閔曰：「鮮卑乘勝氣勁，不可當也，請避之以溢其氣，然後濟師以擊之，可以捷也。」閔怒曰：「吾成師以出，將平幽州，斬慕容雋。今遇恪而避之，人將侮我矣。」乃與恪遇，十戰皆敗之。恪乃以鐵鎖連馬，簡善射鮮卑勇而無剛者五千，方陣而前。閔所乘赤馬曰硃龍，日行千里，左杖雙刃矛，右執鉤戟，順風擊之，斬鮮卑三百餘級。俄而燕騎大至，圍之數周。閔眾寡不敵，躍馬潰圍東走，行二十餘里，馬無故而死，為恪所擒，及董閏、張溫等送之於薊。俊立閔而問之曰：「汝奴僕下才，何自妄稱天子？」閔曰：「天下大亂，爾曹夷狄，人面獸心，尚欲篡逆。我一時英雄，何為不可作帝王邪！」俊怒，鞭之三百，送于龍城，告廆、皝廟。 遣慕容評率眾圍鄴。劉甯及弟崇帥胡騎三千奔于晉陽，蘇亥棄常山奔於新興。鄴中饑，人相食，季龍時宮人被食略盡。冉智尚幼，蔣幹遣侍中繆嵩、詹事劉猗奉表歸順，且乞師于晉。濮陽太守戴施自倉垣次於棘津，止猗，不聽進，責其傳國璽。猗使嵩還鄴復命，幹沈吟未決，施乃率壯士百餘人入鄴，助守三臺，譎之曰：「且出璽付我。今凶寇在外，道路不通，未敢送也。須得璽，當馳白天子耳。天子聞璽已在吾處，信卿至誠，必遣軍糧厚相救餉。」幹以為然，乃出璽付之。施宣言使督護何融迎糧，陰令懷璽送于京師。長水校尉馬願、龍驤田香開門降評。施、融、蔣幹懸縋而下，奔於倉垣。評送閔妻董氏、太子智、太尉申鐘、司空條攸、中書監聶熊，司隸校尉籍羆、中書令李垣及諸王公卿士于薊。尚書令王簡、左僕射張乾、右僕射郎肅自殺。 俊送閔既至龍城，斬於遏陘山。山左右七里草木悉枯，蝗蟲大起，五月不雨，至於十二月。俊遣使者祀之，諡曰武悼天王，其日大雪。是歲永和八年也。","breadcrumbs":"冉閔 » 晉書卷一百七 載記第七","id":"4","title":"晉書卷一百七 載記第七"},"5":{"body":"史臣曰：夫拯溺救焚，帝王之師也；窮凶騁暴，戎狄之舉也。蠢茲雜種，自古為虞，限以塞垣，猶懼侵軼，況乃入居中壤，窺我王政，乘弛紊之機，睹危亡之隙，而莫不嘯群鳴鏑，汨亂天常者乎！ 石勒出自羌渠，見奇丑類。聞鞞上党，季子鑒其非凡；倚嘯洛城，夷甫識其為亂。及惠皇失統，宇內崩離，遂乃招聚蟻徒，乘間煽禍，虔劉我都邑，翦害我黎元。朝市淪胥，若沈航於鯨浪；王公顛仆，譬游魂于龍漠。豈天厭晉德而假茲妖孽者歟！觀其對敵臨危，運籌賈勇，奇謨間發，猛氣橫飛。遠嗤魏武，則風情慷慨；近答劉琨，則音詞倜儻。焚元超於苦縣，陳其亂政之愆；戮彭祖于襄國，數以無君之罪。於是跨躡燕、趙，併吞韓、魏，杖奇材而竊徽號，擁舊都而抗王室，褫毯裘，襲冠帶，釋介胄，開庠序，鄰敵懼威而獻款，絕域承風而納貢，則古之為國，曷以加諸！雖曰凶殘，亦一時傑也。而托授非所，貽厥無謀，身隕嗣滅，業歸攜養，斯乃知人之暗焉。 季龍心昧德義，幼而輕險，假豹姿於羊質，騁梟心於狼性，始懷怨懟，終行篡奪。於是窮驕極侈，勞役繁興，畚鍤相尋，干戈不息，刑政嚴酷，動見誅夷，惵惵遺黎，求哀無地，戎狄殘獷，斯為甚乎！既而父子猜嫌，兄弟仇隙，自相屠膾，取笑天下。墳土未燥，禍亂薦臻，釁起于張豺，族傾于冉閔，積惡致滅，有天道哉！夫從逆則凶，事符影響；為咎必應，理若迴圈。世龍之殪晉人，既窮其酷；永曾之誅羯士，亦殲其類。無德不報，斯之謂乎！ 贊曰：中朝不競，蠻狄爭衡。塵飛五嶽，霧晻三精。狡焉石氏，怙亂窮兵。流災肆慝，剽邑屠城。始自群盜，終假鴻名。勿謂凶醜，亦曰時英。季龍篡奪，淫虐播聲。身喪國泯，其由禍盈。","breadcrumbs":"冉閔 » 史評","id":"5","title":"史評"},"6":{"body":"关于冉闵之争论在网上由来已久，起初以冉吹为主，大概从04年开始，冉闵被吹得神乎其神，乃至出现了各种原（发）创（明）情（历）节（史）吹捧冉闵的小说、网文，还有那篇著名的伪造《杀胡令》，皆是冉吹的发明。 物极必反，吹得太过必然导致被黑得更惨，于是接下来冉黑通过指出冉吹的史实错误将其打脸，并对无脑吹进行辟谣，逐渐占据了评论冉闵的舆论制高点。现在冉闵的话题虽然热度很低，但大部分都是黑他的。 应该承认冉黑的出现对于正确认识历史、防止谣言传播是有不小贡献的。不过矫枉难免过正，现在我只要说一句冉闵是民族英雄，肯定立马被扣上“冉吹”帽子。现在主流观点是：冉闵是汉奸、三姓家奴；冉闵杀胡并不是出于民族大义只是狭隘的争权夺利；前燕给冉闵的谥号“武悼”是恶谥；视冉闵为民族英雄是网络皇汉的发明…… 我认为，以上观点皆不当，是为了反对一个极端走向了另一个极端。不仅如此，我认为，承认冉闵是民族英雄，是合理的。 “你现在还敢给冉闵翻案，读过历史书吗？MDZZ”——估计一定会有人这么说吧。 事实真的如此吗？那么，我就用历史书上的内容来作证，阐明一下我的观点。","breadcrumbs":"冉閔 » 知乎文章—— 冉吹看了沉默，冉黑看了流泪——对冉闵的正本清源","id":"6","title":"知乎文章—— 冉吹看了沉默，冉黑看了流泪——对冉闵的正本清源"},"7":{"body":"这里所说冉闵的所谓“三姓”即是石、李、冉。因为冉闵之父 冉瞻十二岁就被石勒俘获（那时候冉闵肯定还没出生），并成为石虎的养子，因此改姓石，冉闵是石虎养孙，自然也就姓石。冉是他的本姓，冉闵灭后赵，改元称帝，恢复了冉姓。 至于李，就比较奇葩，其出处见于《资治通鉴》： （永和六年，350）春，正月，赵大将军闵欲灭去石氏之迹，托以谶文有「继赵李」，更国号曰卫，易姓李氏，大赦，改元青龙。 有人以此作为依据，声称冉闵改姓了李。不过冉闵当时不是皇帝而是大将军，后赵皇帝是石鉴。这个“易姓改号”是石闵让石鉴做的，尽管是出自 石闵的动机，石鉴当时也并无实权，不过改国号、改元这事当然得由皇帝来做，那么我们可以看出这个“易姓李氏”如果真有，那也是石鉴做的。可能有人要问了，石闵当时也算是石氏宗室一员，那既然皇帝都改姓了皇族是不是也得改？有道理，不过问题在于从史书记载来看，在这“易姓李氏”之后，该姓石的还是姓石，没姓李（能够证明改国号为卫的倒是有一句“卫主鉴密遣宦者赍书召张沈等，使乘虚袭邺”，不过也仅有这一句了）。也就是说，这个“易姓李氏”即使发生了也和没发生一样，其实可以忽略不计。 另外，所谓“三姓家奴”含义就是给三个不同的姓（的政权）做家奴吧？可是冉闵就算说做过家奴也只给后赵石氏做过（前面已经说了所谓“李氏”根本可以忽略），而冉氏代表了他自己建立的政权，哪有自己给自己做家奴一说？所以说冉闵做过“一姓家奴”倒还有道理，所谓“三姓家奴”纯粹胡扯。","breadcrumbs":"冉閔 » 一、所谓“三姓家奴”问题","id":"7","title":"一、所谓“三姓家奴”问题"},"8":{"body":"汉奸，顾名思义指的是汉族的败类。就冉闵早期为后赵政权服务的经历来看似乎确实是汉奸行为，不过冉闵打小就在后赵宫廷长大，又被胡人抚养（《晋书》：“闵幼而果锐，季龙抚之如孙”可以看出），从生活环境来看受胡人影响很深，汉民族意识理应不是很强，为胡人服务也算情有可原，并不像历史上大多数汉奸一样从小在汉文化环境中长大，父母亲戚和身边的人都是汉人，长大以后却背叛汉族投靠异族。评价一个历史人物应该全面，如果只看冉闵早期为后赵服务的经历就说其是汉奸，而忽视了冉闵后期的反胡经历，是不全面的。有人说冉闵反胡纯粹是因为冉闵想要窃取后赵统治权，是统计集团的争权夺利而不是出于民族意识。真的是这样吗？ 协助冉闵夺权并成为冉闵部下的李农，就和乞活军建立了联系 如果冉闵只是为了争权夺利，那么只要夺取后赵统治权，消灭统治集团的其他反对者就行了，用不着反胡啊，冉闵在宣布杀胡令之前也一直在进行权力斗争，冉闵之所以从进行统治集团内部的权力斗争走向反胡的民族斗争，民族意识是起了重要作用的。 按吕思勉意见，冉闵本来没有什么民族意识，冉闵本来只是想清除异己而不是把斗争对象扩大到整个胡人群体： （冉闵借石鉴名义）令城内曰： “与官同心者住，不同心者各任所之。“敕城门不复相禁。\\n——《晋书》 但是之后胡人的行为表明胡人与他根本不同心： 于是赵人（即汉人）百里内悉入城，胡羯去者填门。闵知胡之不为己用也，班令内外赵人，斩一胡首送凤阳门者，文官进位三等，武职悉拜牙门。一日之中，斩首数万。闵躬率赵人诛诸胡羯，无贵贱男女少长皆斩之，死者二十余万，尸诸城外，悉为野犬豺狼所食。屯据四方者，所在承闵书诛之，于时高鼻多须至有滥死者半。\\n——《晋书》 这才是激发出冉闵的汉民族意识，导致他诛胡的导火线（上文说的冉闵反胡有深刻思想背景，可算作深层原因）。 有人认为冉闵从为胡人服务到反胡的转变太快，所以并不是真心反胡，那么结合冉闵反胡的深层原因和导火线可以看出冉闵反胡是出于民族意识所言非虚。 注：其实早在“各任所之”之令之前，冉闵与胡人的矛盾已经显露： 闵、农攻斩伏都等自凤阳至琨华，横尸相枕，〔枕，职任翻。〕流血成渠。 宣令内外，六夷敢称兵仗者斩，〔称，举也。〕 胡人或斩关、或踰城而出者，不可胜数。〔**闵既诛孙伏都等，又禁胡人称兵仗，胡人知祸之将及，故去。**胜，音升。〕 ——《资治通鉴（胡三省注）》","breadcrumbs":"冉閔 » 二、“汉奸”问题与冉闵反胡动机","id":"8","title":"二、“汉奸”问题与冉闵反胡动机"},"9":{"body":"有人说，冉闵反胡并不坚定，主要根据有： 十一月，魏主闵帅步骑十万攻襄国。〔帅，读曰率。骑，奇寄翻；下同。〕署其子太原王胤为大单于、骑骑大将军，以降胡一千配之为麾下。〔单，音蝉。骠，匹妙翻。降，户江翻。〕 光禄大夫韦謏谏曰：「胡、羯皆我之仇敌，〔謏，蓟鸟翻。闵先诛胡、羯，故謏云然。〕 今来归附，苟存性命耳；万一为变，悔之何及。请诛屏降胡，去单于之号，〔屏，必郢翻。去，羌吕翻。〕 以防微杜渐。」闵方欲抚纳群胡，大怒，诛謏及其子伯阳。〔为下降胡执胤降赵张本。〕 ——《资治通鉴》 固然，韦謏的劝谏是出于民族大义，冉闵封其子为大单于、收纳降胡的做法似乎违背反胡初衷，但是纵观历史，无论哪个民族，驱使外族为自己作战的例子屡见不鲜。无论是五胡政权、蒙元、满清还是汉、唐、明，都有利用外族作战的经历，虽然有风险，但却是出于策略。冉闵杀韦謏，可以体现出他的刚愎自用，但如果因此就说冉闵反胡不坚定，那又如何解释冉闵自宣布杀胡直到死都没有停止对胡人作战的事实（不举例了，《晋书》、《资治通鉴》上详细记载了）呢？如何解释冉闵开始反胡斗争后各族胡人一致对抗冉闵呢？ 从一些侧面可以看出冉闵有强烈的民族意识（至少自宣布杀胡以来），且他的反胡态度是坚定的。 赵新兴王祗即皇帝位于襄国，改元永宁。以汝阴王琨为相国， 六夷据州郡【章：十二竹本「郡」下有「拥兵」二字；乙十一行本同；退斋校同。】 者皆应之。 ——《资治通鉴》 辛谧之举、“除胡、羯，以绥华夏”、“锐于廓清”之语还有冉闵遣使告晋的内容说明冉闵志在除胡 三月，姚苌及赵汝阴王琨各引兵救襄国。冉闵遣车骑将军胡睦拒襄于长芦，将军孙威拒琨于黄丘，〕皆败还，士卒略尽。 闵欲自出击之，卫将军王泰谏曰：「今襄国未下，外救云集，若我出战，必覆背受敌，此危道也。不若固垒以挫其锐，徐观其衅而击之。且陛下亲临行陈，如失万全，则大事去矣。」 闵将止，道士法饶进曰：「陛下围襄国经年，无尺寸之功；今贼至，又避不击，将何以使将士乎！且太白入昴，当杀胡王，百战百克，不可失也！」**闵攘袂大言曰：「吾战决矣，敢沮众者** 斩！」乃悉众出，与襄、琨战。 ——《资治通鉴》 冉闵急于与胡人作战（不过冉闵轻敌冒进、刚愎自用，听不进有益的意见，导致这战吃了个大败，冉魏因此元气大伤），也可体现出冉闵坚决反胡的立场。 刘显次于明光宫，去邺二十三里，闵惧，召卫将军王泰议之。泰恚其谋之不从，辞以疮甚。闵亲临问之，固称疾笃。闵怒，还宫，顾谓左右曰：“巴奴，乃公岂假汝为命邪！ 要将先灭群胡，却斩王泰。” ——《晋书》 “要将先灭群胡”体现了冉闵的决心。 己卯，冉闵至蓟。（慕容）儁大赦。**立闵而责之曰：「汝奴仆下才，何得妄称帝﹖」闵曰：「天下大乱，尔曹夷狄** 禽兽之类犹称帝，况我中土英雄，何得不【章：十二行本「何得不」作「何为不得」四字；乙十二行本同；孔本同；张校同。】 称帝邪！」儁怒，鞭之三百，送于龙城。 ——《资治通鉴》 冉闵这段著名的遗言（至少在史书上是他说的最后一句话）也体现了强烈的民族意识。 由此可见，冉闵的反胡斗争是坚决的，冉闵在反胡斗争中表现出的的民族意识是强烈的。如果进行客观全面的评价，说冉闵是汉奸是不妥的。","breadcrumbs":"冉閔 » 三、冉闵反胡斗争是否坚定","id":"9","title":"三、冉闵反胡斗争是否坚定"}},"docInfo":{"0":{"body":0,"breadcrumbs":0,"title":0},"1":{"body":0,"breadcrumbs":0,"title":0},"10":{"body":1,"breadcrumbs":0,"title":0},"2":{"body":0,"breadcrumbs":0,"title":0},"3":{"body":0,"breadcrumbs":0,"title":0},"4":{"body":0,"breadcrumbs":0,"title":0},"5":{"body":0,"breadcrumbs":0,"title":0},"6":{"body":0,"breadcrumbs":0,"title":0},"7":{"body":0,"breadcrumbs":0,"title":0},"8":{"body":0,"breadcrumbs":0,"title":0},"9":{"body":0,"breadcrumbs":0,"title":0}},"length":11},"lang":"English"}}'));